  1	/**
  2	 * QA tests for WP-004: "Open in VS Code" button in the workspace header.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1 — When workspace.initialized is true, an "Open in VS Code" button
  6	 *          appears in the management row between the Setup button position
  7	 *          and the Rename button.
  8	 *   AC2 — When workspace.initialized is false, the "Open in VS Code" button
  9	 *          is not rendered.
 10	 *   AC3 — Clicking the button calls api.workspaces.launch.vscode(projectId, wid)
 11	 *          and shows a success toast on success.
 12	 *   AC4 — If the API call fails, an error toast is shown with the error message.
 13	 *   AC5 — After a successful workspace setup (via the Setup button), the
 14	 *          "Open in VS Code" button is dynamically inserted into the management
 15	 *          row without a full page re-render.
 16	 *
 17	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 18	 * Run individually with:
 19	 *   node --test gui/public/js/views/workspace-detail.vscode-button.test.mjs
 20	 */
 21	
 22	import { test, beforeEach } from 'node:test';
 23	import assert from 'node:assert/strict';
 24	import { JSDOM } from 'jsdom';
 25	
 26	// ---------------------------------------------------------------------------
 27	// jsdom setup — install globals before any module is loaded
 28	// ---------------------------------------------------------------------------
 29	
 30	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>', {
 31	    url: 'http://localhost/',
 32	});
 33	
 34	const { window } = dom;
 35	
 36	globalThis.document    = window.document;
 37	globalThis.window      = window;
 38	globalThis.location    = window.location;
 39	globalThis.HTMLElement = window.HTMLElement;
 40	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 41	
 42	// Stub setInterval / clearInterval so the polling loop never fires.
 43	let _intervalId = 0;
 44	const _intervals = new Map();
 45	globalThis.setInterval = (fn, delay) => {
 46	    const id = ++_intervalId;
 47	    _intervals.set(id, { fn, delay });
 48	    return id;
 49	};
 50	globalThis.clearInterval = (id) => {
 51	    _intervals.delete(id);
 52	};
 53	
 54	// ---------------------------------------------------------------------------
 55	// Minimal fetch mock (required by api.js)
 56	// ---------------------------------------------------------------------------
 57	
 58	globalThis.fetch = async () => ({
 59	    status: 200,
 60	    ok: true,
 61	    statusText: 'OK',
 62	    headers: { get: () => 'application/json' },
 63	    json: async () => ({}),
 64	});
 65	
 66	// ---------------------------------------------------------------------------
 67	// Import dependencies and patch api + toast
 68	// ---------------------------------------------------------------------------
 69	
 70	const { api } = await import('../api.js');
 71	
 72	/** Calls recorded by the launch.vscode spy. */
 73	const vscodeCalls = [];
 74	let vscodeShouldFail  = false;
 75	let vscodeFailMessage = 'VS Code not found';
 76	
 77	if (!api.workspaces.launch) api.workspaces.launch = {};
 78	api.workspaces.launch.vscode = async (projectId, wid) => {
 79	    vscodeCalls.push({ projectId, wid });
 80	    if (vscodeShouldFail) {
 81	        throw new Error(vscodeFailMessage);
 82	    }
 83	    return { success: true };
 84	};
 85	
 86	// Setup call spy — used for AC5
 87	const setupCalls = [];
 88	let setupShouldFail = false;
 89	api.workspaces.setup = async (projectId, wid) => {
 90	    setupCalls.push({ projectId, wid });
 91	    if (setupShouldFail) throw new Error('Setup failed');
 92	    return { results: [] };
 93	};
 94	
 95	// Other required stubs
 96	api.workspaces.health = async () => ({ healthy: true, issues: [] });
 97	api.projects.get      = async () => ({ Id: 'my-project', Repositories: ['repo-alpha'] });
 98	api.status.refresh    = async () => ({
 99	    'repo-alpha': { currentBranch: 'main', localCommits: 0, unfetchedCommits: 0, modifiedFiles: 0, lastActivity: null, hasConflicts: false },
100	});

 1	/**
 2	 * Unit tests for the "Open" button (Actions column) added to the repository
 3	 * status table in workspace-detail.js — WP-005.
 4	 *
 5	 * Covers:
 6	 *   - 4th column header labelled "Actions" is present in the table.
 7	 *   - Each repository row has a 4th cell with a button styled
 8	 *     `btn btn-secondary btn-sm`.
 9	 *   - Clicking the button calls `api.workspaces.launch.githubDesktop(projectId, wid, repoId)`.
10	 *   - When the API call rejects, the button is re-enabled (error path).
11	 *   - Cell index 2 remains the badge cell (Actions column at index 3 does not
12	 *     shift existing indices, so updateStatusTable continues to work).
13	 *
14	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
15	 * Run individually with:
16	 *   node --test gui/public/js/views/workspace-detail.open-button.test.mjs
17	 */
18	
19	import { test, beforeEach } from 'node:test';
20	import assert from 'node:assert/strict';
21	import { JSDOM } from 'jsdom';
22	
23	// ---------------------------------------------------------------------------
24	// jsdom setup — install globals before any module is loaded
25	// ---------------------------------------------------------------------------
26	
27	const dom = new JSDOM('<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>', {
28	    url: 'http://localhost/',
29	});
30	
31	const { window } = dom;
32	
33	globalThis.document    = window.document;
34	globalThis.window      = window;
35	globalThis.location    = window.location;
36	globalThis.HTMLElement = window.HTMLElement;
37	// CSS.escape shim (jsdom may not expose CSS global)
38	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
39	
40	// Stub setInterval / clearInterval so the polling loop never fires and the
41	// process exits cleanly after tests complete.
42	let _intervalId = 0;
43	const _intervals = new Map();
44	globalThis.setInterval = (fn, delay) => {
45	    const id = ++_intervalId;
46	    _intervals.set(id, { fn, delay });
47	    return id;
48	};
49	globalThis.clearInterval = (id) => {
50	    _intervals.delete(id);
51	};
52	
53	// ---------------------------------------------------------------------------
54	// Minimal fetch mock (required by api.js)
55	// ---------------------------------------------------------------------------
56	
57	globalThis.fetch = async () => ({
58	    status: 200,
59	    ok: true,
60	    statusText: 'OK',
61	    headers: { get: () => 'application/json' },
62	    json: async () => ({}),
63	});
64	
65	// ---------------------------------------------------------------------------
66	// Import dependencies and patch api
67	// ---------------------------------------------------------------------------
68	
69	const { api } = await import('../api.js');
70	
71	/** Calls recorded by the launch.githubDesktop spy. */
72	const ghDesktopCalls = [];
73	let ghDesktopShouldFail  = false;
74	let ghDesktopFailMessage = 'GitHub Desktop not found';
75	
76	// Patch launch.githubDesktop on the live api object.
77	if (!api.workspaces.launch) api.workspaces.launch = {};
78	api.workspaces.launch.githubDesktop = async (projectId, wid, repoId) => {
79	    ghDesktopCalls.push({ projectId, wid, repoId });
80	    if (ghDesktopShouldFail) {
81	        throw new Error(ghDesktopFailMessage);
82	    }
83	    return { success: true };
84	};
85	
86	// Stub the remaining api calls used by renderWorkspaceDetail.
87	api.workspaces.get    = async () => ({ Id: 'DEV', id: 'DEV', Description: '', initialized: true, folderPath: '/tmp/dev' });
88	api.workspaces.health = async () => ({ healthy: true, issues: [] });
89	api.projects.get      = async () => ({ Id: 'my-project', Repositories: ['repo-alpha', 'repo-beta'] });
90	api.status.refresh    = async () => ({
91	    'repo-alpha': { currentBranch: 'main', localCommits: 0, unfetchedCommits: 0, modifiedFiles: 0, lastActivity: null, hasConflicts: false },
92	    'repo-beta':  { currentBranch: 'dev',  localCommits: 1, unfetchedCommits: 0, modifiedFiles: 2, lastActivity: null, hasConflicts: false },
93	});
94	api.status.get = api.status.refresh;
95	if (!api.config)          api.config          = {};
96	if (!api.config.polling)  api.config.polling  = {};
97	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
98	
99	const { renderWorkspaceDetail } = await import('./workspace-detail.js');

101	api.status.get = api.status.refresh;
102	if (!api.config)         api.config         = {};
103	if (!api.config.polling) api.config.polling = {};
104	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
105	
106	// Patch workspaces.get to control initialized state
107	let workspaceInitialized = true;
108	api.workspaces.get = async () => ({
109	    Id: 'DEV', id: 'DEV', Description: '', initialized: workspaceInitialized, folderPath: '/tmp/dev',
110	});
111	
112	// Patch the toast module after workspace-detail is imported (module-level spy)
113	// We do this by monkey-patching globalThis so the already-imported toast sees it.
114	// Since workspace-detail.js imports showToast at module load time, we capture it
115	// via a DOM side-effect check instead (toast container not in DOM → silent no-op).
116	// We directly spy on the api / DOM behaviour as the observable side-effects.
117	
118	const { renderWorkspaceDetail } = await import('./workspace-detail.js');
119	
120	// ---------------------------------------------------------------------------
121	// Render helper
122	// ---------------------------------------------------------------------------
123	
124	/**
125	 * Render the workspace-detail view and wait for the async bootstrap to settle.
126	 *
127	 * @param {string} [projectId]
128	 * @param {string} [wid]
129	 * @returns {Promise<{ container: HTMLElement, cleanup: function }>}
130	 */
131	async function renderView(projectId = 'my-project', wid = 'DEV') {
132	    const container = window.document.getElementById('app');
133	    container.innerHTML = '';
134	
135	    const cleanup = renderWorkspaceDetail(container, { id: projectId, wid });
136	
137	    // Poll until a .workspace-mgmt-row is present or we time out.
138	    await new Promise((resolve) => {
139	        let ticks = 0;
140	        const poll = () => {
141	            ticks++;
142	            if (container.querySelector('.workspace-mgmt-row') || ticks > 200) {
143	                resolve();
144	            } else {
145	                Promise.resolve().then(poll);
146	            }
147	        };
148	        Promise.resolve().then(poll);
149	    });
150	
151	    return { container, cleanup };
152	}
153	
154	// ---------------------------------------------------------------------------
155	// Per-test reset
156	// ---------------------------------------------------------------------------
157	
158	beforeEach(() => {
159	    vscodeCalls.length   = 0;
160	    setupCalls.length    = 0;
161	    vscodeShouldFail     = false;
162	    vscodeFailMessage    = 'VS Code not found';
163	    setupShouldFail      = false;
164	    workspaceInitialized = true;
165	    _intervals.clear();
166	    document.getElementById('toast-container').innerHTML = '';
167	});
168	
169	// ---------------------------------------------------------------------------
170	// AC1 — "Open in VS Code" button is present when workspace is initialized
171	// ---------------------------------------------------------------------------
172	
173	test('AC1: "Open in VS Code" button is present in mgmt row when workspace.initialized is true', async () => {
174	    workspaceInitialized = true;
175	    const { container, cleanup } = await renderView();
176	    try {
177	        const mgmtRow = container.querySelector('.workspace-mgmt-row');
178	        assert.ok(mgmtRow, 'mgmt row should exist');
179	
180	        const btns = [...mgmtRow.querySelectorAll('button')];
181	        const vscodeBtn = btns.find((b) => b.textContent.trim() === 'Open in VS Code');
182	        assert.ok(vscodeBtn, '"Open in VS Code" button should be rendered when initialized=true');
183	    } finally {
184	        cleanup();
185	    }
186	});
