188	// ---------------------------------------------------------------------------
189	// AC1 — button appears BEFORE Rename button in the DOM order
190	// ---------------------------------------------------------------------------
191	
192	test('AC1: "Open in VS Code" button appears before the Rename button', async () => {
193	    workspaceInitialized = true;
194	    const { container, cleanup } = await renderView();
195	    try {
196	        const mgmtRow = container.querySelector('.workspace-mgmt-row');
197	        const btns = [...mgmtRow.querySelectorAll('button')];
198	        const vscodeIdx = btns.findIndex((b) => b.textContent.trim() === 'Open in VS Code');
