200	        assert.ok(vscodeIdx !== -1, '"Open in VS Code" button should exist');
201	        assert.ok(renameIdx !== -1, '"Rename" button should exist');
202	        assert.ok(
203	            vscodeIdx < renameIdx,
204	            `"Open in VS Code" (index ${vscodeIdx}) should come before "Rename" (index ${renameIdx})`,
205	        );
206	    } finally {
207	        cleanup();
208	    }
209	});
