253	// AC3 — clicking the button calls api.workspaces.launch.vscode with correct args
254	// ---------------------------------------------------------------------------
255	
256	test('AC3: clicking "Open in VS Code" calls api.workspaces.launch.vscode(projectId, wid)', async () => {
257	    workspaceInitialized = true;
