296	        // Wait for the async handler's finally block to complete.
297	        for (let i = 0; i < 10; i++) {
298	            await new Promise((r) => Promise.resolve().then(r));
299	        }

100	
101	// ---------------------------------------------------------------------------
102	// Render helper
103	// ---------------------------------------------------------------------------
104	
105	/**
106	 * Render the workspace detail view and wait for the async Promise.all inside
